plan = {"title":"Gear with Spokes and Central Hub","assembly_kind":"single_solid","overall_dimensions":{"width":100,"length":100,"height":20},"engineering_requirements":{"functional":["The gear must transmit torque effectively without slipping.","The central hub must fit a 20mm diameter shaft."],"environmental_thermal":["The part should be able to withstand temperatures up to 80°C without deforming."],"structural":["The gear teeth and spokes must be strong enough to handle operational loads.","The overall structure should be rigid and durable."],"manufacturing_cost":["The design should be manufacturable using standard CNC milling or 3D printing.","Minimize material waste and machining time."]},"assumptions":["All dimensions are in millimeters.","The material is assumed to be a standard rigid polymer or aluminum.","The gear profile is a simplified representation and not a standard involute gear profile for this design."],"clarifications":[],"primitives_sequence":[{"sequence_id":1,"name":"gear_base","primitive_type":"cylinder","parameters":{"radius":50,"height":10},"operation":"new","position":[0,0,0],"rotation":[0,0,0],"rationale":"This cylinder forms the main body of the gear, providing the foundational disk from which teeth will be cut."},{"sequence_id":2,"name":"central_hole","primitive_type":"cylinder","parameters":{"radius":10,"height":20},"operation":"cut","position":[0,0,-5],"rotation":[0,0,0],"rationale":"This cut creates the central bore for the shaft, ensuring a precise fit for a 20mm diameter shaft."},{"sequence_id":3,"name":"spoke_cutout_1","primitive_type":"box","parameters":{"width":60,"length":20,"height":10},"operation":"cut","position":[0,0,0],"rotation":[0,0,0],"rationale":"This box is the first of three cutouts to create spokes, reducing material and weight while maintaining structural integrity."},{"sequence_id":4,"name":"spoke_cutout_2","primitive_type":"box","parameters":{"width":60,"length":20,"height":10},"operation":"cut","position":[0,0,0],"rotation":[0,0,60],"rationale":"This second box cutout, rotated 60 degrees, continues the spoke pattern, ensuring symmetrical and balanced design."},{"sequence_id":5,"name":"spoke_cutout_3","primitive_type":"box","parameters":{"width":60,"length":20,"height":10},"operation":"cut","position":[0,0,0],"rotation":[0,0,120],"rationale":"The third box cutout completes the spoke design, providing a lightweight yet strong gear structure."},{"sequence_id":6,"name":"hub_base","primitive_type":"cylinder","parameters":{"radius":20,"height":20},"operation":"join","position":[0,0,-5],"rotation":[0,0,0],"rationale":"This cylinder creates a raised central hub, providing more surface area for the shaft connection and increasing overall rigidity."},{"sequence_id":7,"name":"hub_chamfer_top","primitive_type":"cone","parameters":{"radius1":20,"radius2":18,"height":2},"operation":"cut","position":[0,0,13],"rotation":[0,0,0],"rationale":"This conical cut creates a chamfer on the top edge of the hub, which helps in guiding the shaft during assembly and reduces stress concentrations."},{"sequence_id":8,"name":"gear_tooth_profile","primitive_type":"box","parameters":{"width":8,"length":8,"height":10},"operation":"cut","position":[50,0,0],"rotation":[0,0,0],"rationale":"This box is a profile for cutting a single gear tooth. It will be patterned to create all the gear teeth."},{"sequence_id":9,"name":"hub_chamfer_bottom","primitive_type":"cone","parameters":{"radius1":18,"radius2":20,"height":2},"operation":"cut","position":[0,0,-5],"rotation":[0,0,0],"rationale":"This conical cut adds a chamfer to the bottom edge of the hub, mirroring the top chamfer for symmetry and ease of assembly from either side."}],"contains_freeform":False}

res = build_plan(plan)
if not res["ok"]:
    print(f"Build failed at step {res['failed_step']}: {res['error']}")
else:
    print("Build OK!")
    import cadquery as cq
    cq.exporters.export(res["solid"], "test_gear.stl")
